/// A GRANT'S CHANNEL. `execute` is the one attempt at the confirmed operation.
// interface `admin-authority` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod admin_authority {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, TransportError, VecWriter};
	use alloc::vec::Vec;

	pub const OP_EXECUTE: u16 = 1;

	pub trait Service {
		fn execute(&mut self) -> Result<AdminResult, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:admin")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_EXECUTE => {
				r.finish()?;
				request_handles.clear();
				let result = service.execute();
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v18) => {
							w.u8(1)?;
							v18.write(w)?;
						}
						Err(v19) => {
							w.u8(0)?;
							v19.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn execute(&mut self) -> Option<Result<AdminResult, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_EXECUTE)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(AdminResult::read(r)?) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_admin_admin_authority_execute")]
	fn channel_invoke_execute(chan: u64) -> Option<Result<AdminResult, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.execute()
	}
}

/// What a request connection may ask for: these actions, on targets whose selector starts with this.
#[derive(Clone, Debug, PartialEq)]
pub struct AdminScope {
	pub actions: Vec<AdminAction>,
	pub target_prefix: String,
}

impl AdminScope {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<AdminScope> {
		let mut r = Reader::new(bytes);
		let value = AdminScope::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<AdminScope> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = AdminScope::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		if self.actions.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.actions.len() as u16)?;
		for v20 in self.actions.iter() {
			v20.write(w)?;
		}
		w.bytes_lp(self.target_prefix.as_bytes())?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<AdminScope> {
		let actions = {
			let v21 = r.u16()? as usize;
			let v21 = (v21 <= 2).then_some(v21)?;
			let mut v22 = Vec::new();
			v22.try_reserve_exact(v21).ok()?;
			for _ in 0..v21 {
				v22.push(AdminAction::read(r)?);
			}
			v22
		};
		let target_prefix = {
			let v23 = r.string_lp()?;
			(v23.len() <= 64).then_some(v23)?
		};
		Some(AdminScope { actions, target_prefix })
	}
}

