#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum AdminEvent {
	Requested = 1,
	Granted = 2,
	Declined = 3,
	Consumed = 4,
	Completed = 5,
	Failed = 6,
	OutcomeUnknown = 7,
}

impl AdminEvent {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<AdminEvent> {
		let mut r = Reader::new(bytes);
		let value = AdminEvent::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<AdminEvent> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = AdminEvent::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u8(*self as u8)
	}
	pub fn read(r: &mut Reader) -> Option<AdminEvent> {
		match r.u8()? {
			1 => Some(AdminEvent::Requested),
			2 => Some(AdminEvent::Granted),
			3 => Some(AdminEvent::Declined),
			4 => Some(AdminEvent::Consumed),
			5 => Some(AdminEvent::Completed),
			6 => Some(AdminEvent::Failed),
			7 => Some(AdminEvent::OutcomeUnknown),
			_ => None,
		}
	}
}

/// One decision record, as the journal keeps it.
#[derive(Clone, Debug, PartialEq)]
pub struct AdminRecord {
	pub sequence: u64,
	pub broker_epoch: u64,
	pub request: u64,
	pub launch: u64,
	pub requester: String,
	/// Zero for no action.
	pub action: u8,
	/// SHA-256 of the canonical descriptor; empty before there is one.
	pub digest: Vec<u8>,
	pub event: AdminEvent,
	pub reason: String,
	pub monotonic_ns: u64,
	pub utc_seconds: Option<u64>,
	pub utc_provenance: String,
}

impl AdminRecord {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<AdminRecord> {
		let mut r = Reader::new(bytes);
		let value = AdminRecord::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<AdminRecord> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = AdminRecord::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u64(self.sequence)?;
		w.u64(self.broker_epoch)?;
		w.u64(self.request)?;
		w.u64(self.launch)?;
		w.bytes_lp(self.requester.as_bytes())?;
		w.u8(self.action)?;
		if self.digest.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.digest.len() as u16)?;
		for v39 in self.digest.iter() {
			w.u8(*v39)?;
		}
		self.event.write(w)?;
		w.bytes_lp(self.reason.as_bytes())?;
		w.u64(self.monotonic_ns)?;
		match &self.utc_seconds {
			Some(v40) => {
				w.u8(1)?;
				w.u64(*v40)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		w.bytes_lp(self.utc_provenance.as_bytes())?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<AdminRecord> {
		let sequence = r.u64()?;
		let broker_epoch = r.u64()?;
		let request = r.u64()?;
		let launch = r.u64()?;
		let requester = {
			let v41 = r.string_lp()?;
			(v41.len() <= 64).then_some(v41)?
		};
		let action = r.u8()?;
		let digest = {
			let v42 = r.u16()? as usize;
			let v42 = (v42 <= 32).then_some(v42)?;
			let mut v43 = Vec::new();
			v43.try_reserve_exact(v42).ok()?;
			for _ in 0..v42 {
				v43.push(r.u8()?);
			}
			v43
		};
		let event = AdminEvent::read(r)?;
		let reason = {
			let v44 = r.string_lp()?;
			(v44.len() <= 64).then_some(v44)?
		};
		let monotonic_ns = r.u64()?;
		let utc_seconds = if r.tag()? { Some(r.u64()?) } else { None };
		let utc_provenance = {
			let v45 = r.string_lp()?;
			(v45.len() <= 16).then_some(v45)?
		};
		Some(AdminRecord { sequence, broker_epoch, request, launch, requester, action, digest, event, reason, monotonic_ns, utc_seconds, utc_provenance })
	}
}

#[derive(Clone, Debug, PartialEq)]
pub struct AdminJournalPage {
	pub records: Vec<AdminRecord>,
	/// The oldest sequence still retained.
	pub oldest: u64,
	/// The sequence after the last one returned.
	pub next: u64,
	/// Records the emergency ring had to drop.
	pub evicted: u64,
}

impl AdminJournalPage {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<AdminJournalPage> {
		let mut r = Reader::new(bytes);
		let value = AdminJournalPage::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<AdminJournalPage> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = AdminJournalPage::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		if self.records.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.records.len() as u16)?;
		for v46 in self.records.iter() {
			v46.write(w)?;
		}
		w.u64(self.oldest)?;
		w.u64(self.next)?;
		w.u64(self.evicted)?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<AdminJournalPage> {
		let records = {
			let v47 = r.u16()? as usize;
			let v47 = (v47 <= 16).then_some(v47)?;
			let mut v48 = Vec::new();
			v48.try_reserve_exact(v47).ok()?;
			for _ in 0..v47 {
				v48.push(AdminRecord::read(r)?);
			}
			v48
		};
		let oldest = r.u64()?;
		let next = r.u64()?;
		let evicted = r.u64()?;
		Some(AdminJournalPage { records, oldest, next, evicted })
	}
}

/// THE OPERATOR'S READ VIEW of the decision journal. No requester holds it.
// interface `admin-journal` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod admin_journal {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, TransportError, VecWriter};
	use alloc::vec::Vec;

	pub const OP_READ: u16 = 1;

	pub trait Service {
		fn read(&mut self, from: u64) -> Result<AdminJournalPage, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:admin")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_READ => {
				let from = r.u64()?;
				r.finish()?;
				request_handles.clear();
				let result = service.read(from);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v49) => {
							w.u8(1)?;
							v49.write(w)?;
						}
						Err(v50) => {
							w.u8(0)?;
							v50.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn read(&mut self, from: &u64) -> Option<Result<AdminJournalPage, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_READ)?;
			w.u32(corr)?;
			w.u64(*from)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(AdminJournalPage::read(r)?) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_admin_admin_journal_read")]
	fn channel_invoke_read(chan: u64, from: &u64) -> Option<Result<AdminJournalPage, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.read(from)
	}
}

