#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum AdminProbeFault {
	None = 0,
	/// Perform the effect and do not answer.
	LoseReply = 1,
	/// Refuse the next execution.
	Fail = 2,
}

impl AdminProbeFault {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<AdminProbeFault> {
		let mut r = Reader::new(bytes);
		let value = AdminProbeFault::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<AdminProbeFault> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = AdminProbeFault::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u8(*self as u8)
	}
	pub fn read(r: &mut Reader) -> Option<AdminProbeFault> {
		match r.u8()? {
			0 => Some(AdminProbeFault::None),
			1 => Some(AdminProbeFault::LoseReply),
			2 => Some(AdminProbeFault::Fail),
			_ => None,
		}
	}
}

